package dev.krillin.bifrost.core.mapping;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import java.math.BigDecimal;
import java.time.OffsetDateTime;
import static dev.krillin.bifrost.core.mapping.MappingJson.*;

/** Independent finite result-set definition validator. No SQL parser/driver/runtime IO. */
final class RecordMappings {
 interface Checker {void check(List<JsonNode> derived) throws Exception;}
 static ObjectNode pin(JsonNode d) throws Exception{return MappingTemplates.pin(d);}
 static String pair(JsonNode d){return text(d,"id")+"@"+text(d,"version");}
 static String evidenceId(JsonNode r){return "record-"+text(r,"id")+"-"+text(r,"version").replace('.','-');}
 static Map<String,JsonNode> fields(JsonNode r){Map<String,JsonNode> fs=new LinkedHashMap<>();for(JsonNode f:r.path("resultSchema").path("fields"))require(fs.put(text(f,"fieldId"),f)==null,"record.field-duplicate");return fs;}
 static void timestamp(String s){require(!s.endsWith("-00:00"),"record.timestamp");OffsetDateTime.parse(s);}
 static void defaultValue(JsonNode f,JsonNode v){String typ=text(f,"valueType");if(typ.equals("String"))require(v.isTextual(),"record.default-type");else if(typ.equals("Boolean"))require(v.isBoolean(),"record.default-type");else{require(v.isTextual()&&v.asText().length()<=256&&v.asText().matches("[+-]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]{1,4})?"),"record.default-type");BigDecimal d=new BigDecimal(v.asText());require(Math.abs(d.scale())<=1000,"record.default-range");if(typ.equals("Int32"))require(d.stripTrailingZeros().scale()<=0&&d.compareTo(new BigDecimal("-2147483648"))>=0&&d.compareTo(new BigDecimal("2147483647"))<=0,"record.default-range");else require(d.abs().compareTo(new BigDecimal("1.7976931348623157e308"))<=0,"record.default-range");}}
 static void basic(JsonNode r,JsonNode t) throws Exception {
  schema(r,"record-mapping");timestamp(text(r,"authoredAt"));timestamp(text(r.path("provenance"),"capturedAt"));MappingTemplates.template(t);require(r.path("templateRef").equals(pin(t)),"record.template-pin");require(r.path("semanticDefinitionRef").equals(object().put("id",text(t.path("model"),"id")).put("version",text(t.path("model"),"version"))),"record.model-ref");for(String c:text(r,"version").split("\\."))Integer.parseInt(c);
  JsonNode rs=r.path("resultSchema");Map<String,JsonNode> fs=fields(r);Set<String> keys=new HashSet<>();for(JsonNode k:rs.path("keyFields")){JsonNode f=fs.get(k.asText());require(keys.add(k.asText())&&f!=null&&text(f,"valueType").equals("String")&&!f.path("nullable").asBoolean(),"record.key-contract");}
  JsonNode q=rs.path("query");require(text(q,"language").equals("none")?q.path("text").isNull():q.path("text").isTextual()&&!q.path("text").asText().isBlank(),"record.query-metadata");Map<String,JsonNode> slots=new HashMap<>();for(JsonNode s:t.path("slots"))slots.put(text(s,"slotId"),s);Set<String> bound=new HashSet<>();
  for(JsonNode binding:r.path("bindings")){String sid=text(binding,"slotId");require(bound.add(sid)&&slots.containsKey(sid),"record.slot-bindings");JsonNode f=fs.get(text(binding,"fieldId"));require(f!=null,"record.field-missing");ObjectNode sig=object();sig.set("rawRepresentation",object().put("valueType",text(f,"valueType")));sig.set("unit",f.path("unit"));sig.put("inputStage",text(f,"inputStage"));sig.putNull("fixedArray");require(sig.equals(slots.get(sid).path("signature")),"record.slot-signature:"+sid);boolean reject=text(binding,"nullPolicy").equals("reject");require(reject?binding.path("defaultValue").isNull():f.path("nullable").asBoolean()&&!binding.path("defaultValue").isNull(),"record.null-policy");if(!reject)defaultValue(f,binding.path("defaultValue"));}
  if(text(r,"schemaVersion").equals("2.22.0"))RecordBroadcast.basic(r,t,slots,bound);require(bound.equals(slots.keySet()),"record.slot-bindings");JsonNode out=r.path("output");require(text(out,"mode").equals("object")?Set.of("reject","null").contains(text(out,"zeroPolicy"))&&text(out,"manyPolicy").equals("reject")&&out.path("maxRows").asInt()==1:Set.of("reject","empty").contains(text(out,"zeroPolicy"))&&text(out,"manyPolicy").equals("all"),"record.cardinality-contract");JsonNode selection=r.path("selection");require(text(selection,"kind").equals("all")?selection.path("key").isEmpty():selection.path("key").size()==rs.path("keyFields").size(),"record.selection-contract");
  ArrayNode evidence=JSON.createArrayNode();ObjectNode e=object().put("artifactId",evidenceId(r));e.set("locator",object().put("kind","text-line").put("line",1));evidence.add(e);require(evidence.equals(r.path("evidenceRefs")),"record.evidence-contract");
 }
 static ObjectNode compile(JsonNode r,JsonNode t) throws Exception {
  basic(r,t);ArrayNode identity=JSON.createArrayNode().add(text(r,"id")).add(text(r,"version")).addNull();String app="record-"+sha(bytes(identity)).substring(0,24);Map<String,JsonNode> fs=fields(r);ArrayNode sources=JSON.createArrayNode(),bindings=JSON.createArrayNode();
  for(JsonNode b:r.path("bindings")){JsonNode f=fs.get(text(b,"fieldId"));String id=app+"-"+text(b,"slotId");ObjectNode s=object().put("kind","source-definition").put("schemaVersion","2.7.0").put("id",id).put("version","1.0.0").put("equipmentInstanceId",text(r,"equipmentInstanceId")).putNull("connectionProfileRef").put("accessProfileRef","external-value-v1").put("sourceKind","external-value").put("accessMode","read").put("status","ready").put("rawAddressText",text(r.path("resultSchema"),"valueKey")+"."+text(f,"fieldId")).putNull("addressRadix").put("inputStage",text(f,"inputStage")).putNull("viewOf");s.set("access",object().put("kind","external-value").put("providerRef",text(r.path("resultSchema"),"providerRef")).put("valueKey",text(r.path("resultSchema"),"valueKey")+"."+text(f,"fieldId")).put("expressionLanguage","none").putNull("expression"));s.set("rawRepresentation",object().put("mode","typed").put("valueType",text(f,"valueType")));s.set("unit",f.path("unit").deepCopy());s.set("evidenceRefs",r.path("evidenceRefs").deepCopy());sources.add(s);ObjectNode bind=object().put("slotId",text(b,"slotId"));bind.set("sourceRef",object().put("id",id).put("version","1.0.0"));bindings.add(bind);}
  if(text(r,"schemaVersion").equals("2.22.0")){for(JsonNode source:r.path("commonSources"))sources.add(source.deepCopy());for(JsonNode b:r.path("commonBindings")){ObjectNode bind=object().put("slotId",text(b,"slotId"));bind.set("sourceRef",object().put("id",text(b.path("sourceRef"),"id")).put("version",text(b.path("sourceRef"),"version")));bindings.add(bind);}}
  ObjectNode a=object().put("kind","template-application").put("schemaVersion","2.19.0").put("id","application-"+app+"-r1").put("version","1.0.0").put("applicationId",app).put("revision",1).putNull("previousApplicationRef").put("equipmentInstanceId",text(r,"equipmentInstanceId")).put("targetLabel",text(r,"label")).put("authoredBy",text(r,"authoredBy")).put("authoredAt",text(r,"authoredAt"));a.set("templateRef",pin(t));a.set("bindings",bindings);a.set("sourceSnapshots",sources);a.set("generated",JSON.createArrayNode().add(object()).add(object()).add(object()));a.set("generated",MappingTemplates.compile(t,a));return a;
 }
 record History(Map<String,JsonNode> templates,Map<String,List<JsonNode>> records){}
 static History histories(Collection<JsonNode> docs) throws Exception {
  RecordBroadcast.history(docs,List.of());var recipes=MappingTemplates.histories(docs);Map<String,JsonNode> templates=new HashMap<>();recipes.templates().values().forEach(v->v.forEach(t->templates.put(pair(t),t)));Map<String,JsonNode> unique=new TreeMap<>();for(JsonNode r:docs)if(text(r,"kind").equals("record-mapping")){String k=pair(r);require(!unique.containsKey(k)||unique.get(k).equals(r),"record.history-conflict");unique.put(k,r);}require(unique.size()<=128,"record.history-limit");Map<String,List<JsonNode>> groups=new TreeMap<>();Map<String,String> signatures=new HashMap<>();
  for(JsonNode r:unique.values()){JsonNode t=templates.get(pair(r.path("templateRef")));require(t!=null,"record.template-missing");basic(r,t);groups.computeIfAbsent(text(r,"id"),k->new ArrayList<>()).add(r);String k=pair(r.path("resultSchema")),h=sha(bytes(r.path("resultSchema")));require(!signatures.containsKey(k)||signatures.get(k).equals(h),"record.result-schema-conflict");signatures.put(k,h);}
  for(List<JsonNode> versions:groups.values()){require(versions.size()<=32,"record.version-limit");versions.sort(MappingTemplates::compareVersion);JsonNode previous=null;for(JsonNode r:versions){require(r.path("previousMappingRef").equals(previous==null?JSON.nullNode():pin(previous)),"record.version-chain");require(previous==null||text(r,"equipmentInstanceId").equals(text(previous,"equipmentInstanceId")),"record.equipment-change");previous=r;}}return new History(templates,groups);
 }
 static void validate(Collection<JsonNode> docs,Collection<JsonNode> prior,Checker checker) throws Exception {
  List<JsonNode> all=new ArrayList<>(prior);all.addAll(docs);var history=histories(all);Map<String,JsonNode> models=new HashMap<>();for(JsonNode d:docs)if(text(d,"kind").equals("semantic-definition"))models.put(pair(d),d);
  for(JsonNode r:docs)if(text(r,"kind").equals("record-mapping")){JsonNode t=history.templates().get(pair(r.path("templateRef")));if(text(r,"schemaVersion").equals("2.22.0"))RecordBroadcast.sourcePins(r,docs);require(t.path("model").equals(models.get(pair(r.path("semanticDefinitionRef")))),"record.semantic-pin");ObjectNode a=compile(r,t);if(checker!=null){List<JsonNode> derived=new ArrayList<>(MappingTemplates.list(a.path("sourceSnapshots")));derived.addAll(MappingTemplates.list(a.path("generated")));checker.check(derived);}}
 }
 static List<JsonNode> governance(Collection<JsonNode> docs) throws Exception {
  if(docs.stream().noneMatch(d->text(d,"kind").equals("record-mapping")))return List.of();var history=histories(docs);List<JsonNode> out=new ArrayList<>();for(JsonNode r:docs)if(text(r,"kind").equals("record-mapping")){ObjectNode a=compile(r,history.templates().get(pair(r.path("templateRef"))));List<JsonNode> generated=MappingTemplates.list(a.path("generated"));((ObjectNode)generated.get(generated.size()-1)).put("id","record-"+text(r,"id")+"-"+text(r,"version"));out.addAll(generated);}return out;
 }
}
